// Arke Player · writes its design master, `Arke Player.dc.html`, and a static review page.
//   node design/build.mjs
// The Player master is its own document: turns P1, P2… and frames P1a… never share a number with
// the Studio master's. It borrows the Studio master's document chrome (the dv-* styles) so the two
// read alike, and cites Studio turns by link into a sibling ArkeStudio checkout. Then: node design/check.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { FRAMES } from './frames.mjs';
import { esc } from './view.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const read = (name) => fs.readFileSync(path.join(here, name), 'utf8');
const write = (name, content) => fs.writeFileSync(path.join(here, name), content);
const TOKENS = 'tokens';
const DATE = '20 October 2026';

/** A Studio turn, cited by link into the Studio master. */
const STUDIO = '../../ArkeStudio/design-system/Arke%20Studio.dc.html';
const S = (n) => `<a class="dv-oid" href="${STUDIO}#t${n}">${n}</a>`;
/** A frame or turn in this master. */
const F = (id) => `<a class="dv-oid" href="#${id.toLowerCase()}">${id}</a>`;

const TURNS = [
  {
    id: 'p1', name: 'The shape of Arke Player — first open, Home, Library, a world, a production',
    lead: `Asked: a phone app, Arke Player, that plays what is made in Arke — productions from worlds shared through Arke, and Arke packages a person adds — reusing the players already drawn in the Studio master. The Studio stays where things are made; the Player is where they are watched, heard, read and played.`,
    rules: [
      ['What it plays', `Arke Player is a phone app for <b>publications</b>: films, micro dramas, interactive movies, visual novels, audiobooks, audio dramas and books. A publication is a frozen edition with its own manifest (SPEC-048, <code>publication.json</code>). The Player <b>never opens a world’s source</b>: no sheets, prompts, takes, settings or unpublished work reach it, and nothing in it edits, generates or spends.`],
      ['Two ways in, no gate', `Things arrive as a <b>share</b> through an Arke account (${F('P2a')}) or as a <b>file</b> added from the phone — an Arke package, or a book, a PDF, audio or video in a standard format (${F('P2c')}, ${F('P7')}). Neither needs the other: a file plays with no account. First open (${F('P1a')}) is the wordmark over a world’s picture and two presses, <code>Sign in with Arke ↗</code> and <code>Add a file</code>; no tour, no sentence.`],
      ['Four tabs', `<code>Home</code>, <code>Library</code>, <code>Downloads</code>, <code>You</code>, in a bar <code>84</code> high (<code>56</code> pressable, the rest the home indicator’s), icon over label, the current tab in full ink. A page pushed from a tab keeps the bar. On a Fold the bar becomes an <code>88</code>-wide rail (${F('P6e')}).`],
      ['Home is for going on', `Three sections, each absent when empty (${F('P1b')}): <b>Continue</b> — what is in progress, last played first, at most <code>8</code>, cards <code>300 × 169</code>; <b>New</b> — productions added to a shared world since this device last looked, the world on the kind line; <b>Worlds</b> — every world, <code>240 × 135</code>. A Continue card names the kind, the title and where you are as data (<code>Chapter 7 · 19 min left</code>, <code>38 min left</code>, <code>Episode 13</code>, <code>The drowned quarter</code>) over a <code>3</code>-high line of progress. An interactive or visual novel card names its scene and draws no line, because a route has no length (Studio ${S(156)}). The round press resumes in the player; the card opens the production. Finished things leave Continue.`],
      ['Library is every world', `A card per world, <code>358 × 190</code>, under the chips <code>All · Shared · Added</code>, with <code>+</code> (Add a file) in the head (${F('P1c')}). A shared world’s meta line is who shared it and the count (<code>Helen Marsh · 6 productions</code>); an added one’s is <code>Added · 3 productions · 1.4 GB</code>.`],
      ['A world’s page', `The world’s key art as the hero, <code>300</code> high under a back press and ⋯, its name in <code>text-3xl</code>, one meta line, and its logline in at most two lines — the author’s words as published, or nothing (${F('P1d')}). Then its productions grouped by what a person does: <b>Watch</b> (film, micro drama), <b>Play</b> (interactive movie, visual novel), <b>Listen</b> (audiobook, audio drama), <b>Read</b> (a book with no narration). A group with nothing in it is not drawn. A book with its narration is one production, under Listen, its kind line <code>Audiobook · Book</code>. Tiles are <code>160</code> wide, 16:9, with title, kind and length, and the line of progress.`],
      ['A production’s page', `Studio ${S(199)}’s show page on a phone (${F('P1e')}, ${F('P1f')}): the backdrop, the title in <code>text-3xl</code>, <b>one meta line</b> (<code>Audiobook · Book · 9 h 40 m · Read by Odile’s voice</code>), the primary full width and <code>50</code> high — <code>Play</code>, or <code>Continue · Chapter 7 · 12:04</code> when this device holds a place — then one row: the second way in (<code>Read</code>, for a book with narration), the download with its size, and ⋯ (<code>Start over</code>, <code>Remove download</code>, <code>Details</code>). Under it what it is made of: <code>Chapters</code> or <code>Episodes</code> as rows (a <code>128</code> thumbnail with its listened line, the title, the length, a downloaded mark); a micro drama’s episodes as a 4-across grid of 9:16 thumbnails. <code>Cast</code> is drawn only when the publication carries credits.`],
      ['The dock', `Audio that plays while its player is closed docks above the tabs (${F('P1d')}): <code>60</code> high, inset <code>8</code>, a <code>2</code>-high progress line on its top edge, the picture of the moment, the title over where, back 15 and play or pause; a press opens the player (Studio ${S(199)}). Video does not dock: closing its player pauses it and keeps its place, and the phone’s own picture in picture is offered where the system has it.`],
      ['Theme', `The shelves — Home, Library, Downloads, You and the sheets over them — follow the phone’s light or dark. A hero, a picture card and every player are on the media overlay colours whatever the theme (Studio ${S(156)}, ${S(199)}).`],
      ['Words', `Labels only: Home, Library, Downloads, You, Continue, New, Worlds, Watch, Play, Listen, Read, Chapters, Episodes, and counts, sizes and times as data. No sentence under a title (Studio ${S(137)}).`],
    ],
    next: `Try next: “Home with nothing yet” · “a world with one production” · “Details from ⋯”`,
  },
  {
    id: 'p2', name: 'Getting worlds in — a share through an Arke account, a package from a file',
    lead: `A shared world arrives as a link; a package arrives as a file. Both end as a world in Library.`,
    rules: [
      ['A share opens from its link', `A share link opens the Player (an app link; without the Player, its store page). The sheet <code>Shared with you</code> shows the world’s key art and name, who shared it — picture and name — and the count, then <code>Open</code>; signed out, <code>Sign in with Arke ↗</code> and <code>Not now</code> (${F('P2a')}). Signed in to an account the share was not made for, the sheet says <code>Not shared with this account</code> and offers <code>Switch account</code>.`],
      ['Sign-in is the browser’s', `As Studio ${S(151)}: no password field in the Player. The press hands off to the system’s browser sheet, the presses give way to <code>waiting for the browser</code> and <code>Cancel</code> (${F('P2b')}), and the Player keeps the session. <code>Arke account</code> is the only account it knows.`],
      ['What a share is', `A share gives one account the productions its owner chose from a world, as publications, under the world’s name, key art and logline. The owner can add productions — they appear under <code>New</code> — and can stop sharing. Who and what is set in the Studio, in a Share sheet this master does not draw. A shared production <b>streams</b> from the Arke cloud until it is downloaded (${F('P6a')}).`],
      ['A share that ends', `The world stays in Library, greyed, with <code>No longer shared</code> and <code>Remove</code> on its card (${F('P2g')}). Nothing in it opens, and its downloads are deleted the next time the Player reaches the cloud. Its places are kept until Remove, so a share made again resumes where it was.`],
      ['Adding a file', `<code>+</code> in Library, and <code>Add a file</code> on first open, open <code>Add</code>, a sheet of two — <code>Choose files</code> (the system’s picker, several at once) and <code>Paste a link</code> (<code>https</code> only) — and what it takes as one line of data (${F('P2c')}). A file also arrives from the system’s Open in and Share menus. Accepted: the standard formats of ${F('P7')}, and a <b>world package</b> — a ZIP holding the world’s name, logline and key art and one or more publications, each with its own <code>publication.json</code> — or one publication’s ZIP. The world package is a proposal; its format is owed to SPEC-048 before it is built.`],
      ['Checked before it is shown', `Free space is checked first: a package larger than what is free is refused before it is copied. The Player then copies the file into its own storage and checks every asset’s byte length and SHA-256 against its manifest: <code>Checking</code>, the file’s name and size, a bar, <code>212 of 418 files</code>, <code>Cancel</code> (${F('P2d')}). Nothing in a package plays before the check passes.`],
      ['Ready', `The summary is what the manifests say (${F('P2e')}): the world’s picture and name, <code>made 12 Oct 2026 · 3 productions · 1.4 GB</code>, each production with its kind and size under <code>Inside</code>, the space it takes against what is free, and <code>Add to library</code>. Closing deletes the copy.`],
      ['Refused in one clause', `A refusal is its title (${F('P2f')}): <code>3 files do not match</code>, <code>Made with a newer Arke</code> (with <code>Update</code>), <code>Not an Arke package</code>, <code>Needs 1.4 GB · 0.9 GB free</code>. Nothing partial is added and the copy is deleted. <code>Choose another file</code> and <code>Close</code>.`],
      ['A package is the person’s', `An added world is removed only by <code>Remove</code>, needs no account and is never uploaded to one.`],
    ],
    next: `Try next: “Not shared with this account” · “a package arriving from Open in” · “Made with a newer Arke”`,
  },
  {
    id: 'p3', name: 'Watching — a film, a micro drama',
    lead: `The Player hosts the players the Studio already draws; a film and a micro drama get the transport a phone needs.`,
    rules: [
      ['One player, three homes', `The players are Studio ${S(156)}’s, ${S(174)}’s and ${S(186)}’s: the same framework-free modules the Studio previews with and the packages carry (156: one player, two homes). The Player runs those modules and adds only its close (⌄, back to where the player was opened) and the phone’s media session around them — lock screen and headset controls, background audio, picture in picture, casting. What plays in a browser from a package plays the same in the Player.`],
      ['A film', `The picture is the page (156): letterboxed, never cropped, on the overlay colours. Held upright, the picture sits in the middle with the chrome over two scrims (${F('P3a')}); turned, it fills the height (${F('P3b')}). A film’s scrubber runs across the whole film, since a film has a length. The transport: <code>Captions</code>, back <code>10</code>, play or pause <code>64</code>, forward <code>10</code>, full screen; the time as <code>54:40 / 1:32:40</code>; <code>Cast</code> at the top. The chrome rests after <code>2.5s</code> while playing and never while paused.`],
      ['A micro drama is a feed', `One episode a screen, 9:16, full bleed (${F('P3c')}). Swipe up for the next episode, down for the one before; a tap pauses. The top holds ⌄ and the production over <code>Episode 13</code>; a column at the right edge holds <code>Episodes</code>, <code>Captions</code> and <code>More</code>, <code>44</code> across with their names; a <code>3</code>-high scrubber sits above the home indicator, the episode’s number and title over it. At an episode’s end the next begins (<code>Autoplay next</code>, on by default, in You).`],
      ['Episodes', `A glass sheet over the picture, which keeps playing (${F('P3d')}): the count, <code>1–20 · 21–40</code>, and the episodes as numbered tiles five across, <code>48</code> high — seen ones dimmed, the current one inverted. A press plays that episode from its kept place, else its start.`],
      ['Captions', `A sheet of the publication’s text tracks by their label, <code>Off</code> first, the chosen one checked, then <code>Size</code> <code>S · M · L</code> (${F('P3e')}). The choice is kept on the device and applies to every production that carries that language; one without it plays with captions off.`],
    ],
    next: `Try next: “a series with seasons” · “casting to a TV” · “a micro drama paused”`,
  },
  {
    id: 'p4', name: 'Playing — an interactive movie, a visual novel',
    lead: `Studio 156’s interactive player and 174’s visual novel, on a phone and inside the Player.`,
    rules: [
      ['An interactive movie is 156’s player', `On a phone the choices stack full width where the thumb is, <code>58</code> high, in authored order, the first in focus, <code>Replay scene</code> under them; captions and the route sit at the top (${F('P4a')}, Studio ${S(156)}i). Nothing counts down: untimed is the only built behaviour (156).`],
      ['The route', `A glass sheet over the picture (${F('P4b')}): each scene watched with its <code>96 × 54</code> still, the choice taken between them with <code>Choose again</code>, and <code>Start over</code>. No endings found, no percentages (156).`],
      ['An ending is a title', `<code>ENDING</code>, the ending’s title in <code>text-4xl</code>, the route as stills with the choices taken in one line, then <code>Start again</code> and <code>Back to last choice</code> (${F('P4c')}, 156e on a phone).`],
      ['A visual novel is 174’s player', `The box above the home indicator, <code>12</code> in from each edge, the speaker’s tab and the line in <code>text-lg</code>; a tap anywhere moves on; <code>Auto</code>, <code>Log</code> and ⋯ (Route, Start over) at the top (${F('P4d')}, Studio ${S(174)}g). <code>Log</code> is a glass sheet of the scene’s lines up to now, newest last, each with its play (${F('P4e')}, 174e).`],
      ['Where you are', `A place is kept on the device, per routing version (156f): a scene and a time, or a scene and a beat. On a production’s page <code>Continue</code> names the scene; <code>Start over</code> is in ⋯.`],
    ],
    next: `Try next: “three and four choices on a phone” · “a visual novel at 16:9 on a phone” · “the route of a long story”`,
  },
  {
    id: 'p5', name: 'Listening and reading — an audiobook, an audio drama, a book',
    lead: `Studio 186’s audiobook player with 211’s Slow push and 212’s two lines, an audio drama with its transcript, and the book an edition carries.`,
    rules: [
      ['An audiobook is 186’s player', `The picture of the moment fills the top <code>62%</code> (${F('P5a')}); <code>Slow push</code> sits under the title as a labelled switch <code>44</code> high (Studio ${S(211)}); <code>Text</code> shows only the current phrase, at most two lines at <code>text-lg</code>, centred above the transport (Studio ${S(212)}). The transport: previous chapter, back <code>15</code>, play or pause <code>64</code>, forward <code>30</code>, next chapter; under it the speed, the sleep choice and <code>Text</code>. <code>Chapters</code> and ⋯ at the top (Studio ${S(186)}).`],
      ['Chapters', `A glass sheet (${F('P5b')}): each chapter’s number, title and length, a check when finished, the playing one with its line of progress, a downloaded mark. A chapter the edition does not hold is not listed: a publication carries only chapters read whole (186).`],
      ['Speed and sleep', `One sheet (${F('P5c')}): speed <code>0.8× · 1.0× · 1.2× · 1.5× · 2×</code>, the pitch kept (186); sleep <code>Off</code>, <code>End of chapter</code>, <code>15 min</code>, <code>30 min</code>, <code>60 min</code>. Both kept on the device.`],
      ['An audio drama', `The episode’s picture as a 16:9 card at the top, then the edition’s transcript (Studio ${S(230)}): the speaker in label caps over the line, the line being heard in full ink and the rest at <code>46%</code>, a sound cue in brackets and italics (${F('P5d')}). The transcript follows the audio; a press on a line plays from it. The transport is the audiobook’s, with <code>Transcript</code> and <code>Episodes</code>.`],
      ['A book', `The edition’s EPUB on the shelves’ theme (${F('P5e')}): ⌄, the chapter, <code>Aa</code> (size; Paper, Sepia, Night) and Contents at the top; the text; at the foot the page in the chapter (<code>12 of 30</code>) with its line, and <code>Listen</code> when the edition has narration. Listen opens that chapter in the audiobook at its kept place, else its start. Reading and listening keep separate places (Studio ${S(224)}).`],
      ['The phone’s controls', `Audio plays with the screen locked; the lock screen and headset drive it, with the picture of the moment as the artwork (186).`],
    ],
    next: `Try next: “an audio drama’s episodes” · “Aa open” · “the lock screen”`,
  },
  {
    id: 'p6', name: 'Offline, You, adult content and the Fold',
    lead: `What is on the phone, the device’s settings, the one gate a share can carry, and the Player open on a Fold7.`,
    rules: [
      ['Downloads', `A shared production plays from the cloud until it is downloaded; an added package is always on the phone. The tab opens on the space Arke Player takes against the rest and what is free, then <b>Shared</b> downloads — each with its size and a downloaded mark, <code>Downloading · 42%</code> with its line, or <code>Waiting for Wi-Fi</code> — then <b>Added</b> packages (${F('P6a')}). ⋯ on a row removes it. Downloads wait for Wi-Fi while <code>Wi-Fi only</code> is on.`],
      ['Offline', `Without a network the head of Home says <code>Offline</code> (${F('P6d')}). What is on the phone plays as ever; a shared production not downloaded is greyed with <code>offline</code> on its kind line and does not open. Places made offline are kept and sent on the next connection.`],
      ['You', `The account — picture, name, address, <code>Account ↗</code> (Studio ${S(151)}) and <code>Sign out</code> — then <b>Playback</b>: <code>Captions</code>, <code>Text</code>, <code>Slow push</code>, <code>Autoplay next</code>; <b>Downloads</b>: <code>Wi-Fi only</code>, <code>Storage</code>; <b>Content</b>: <code>Adult content</code>; then About (${F('P6b')}), in Studio ${S(149)}’s row grammar. Every setting is this device’s.`],
      ['Adult content', `Off by default. A production its owner marked adult shows blurred, with <code>18+</code>, and does not open; a press offers <code>Adult content is off</code> with <code>I am 18 or older · Turn on</code> and <code>Not now</code> (${F('P6c')}). Turning it on is a personal choice made once on this device and undone in You (Studio ${S(154)}).`],
      ['On a Fold', `At <code>600</code> wide and over the tabs become an <code>88</code>-wide rail, Continue cards are <code>420</code> wide and the shelves widen (${F('P6e')}). A player keeps the picture the page — 16:9 across the top at the full width — with the words and the transport centred under it at <code>640</code>, the words at <code>text-2xl</code> (${F('P6f')}). Bands: under <code>600</code> a phone; <code>600</code> to <code>1099</code> a Fold or a tablet.`],
      ['Implementation boundary', `Nothing here is built. The Arke cloud — accounts, shares, streaming — does not exist yet: the Studio’s account seam answers <code>Arke cloud is not available yet</code>. The first build can ship packages, the players and downloads, and take shares when the cloud arrives. The world package and the share model are owed to the specs (SPEC-048, SPEC-025) before either is built.`],
    ],
    next: `Try next: “Storage open” · “a download failed” · “the Fold folded mid-play”`,
  },
  {
    id: 'p7', name: 'Files in standard formats — EPUB, PDF, CBZ, audio and video beside Arke packages',
    lead: `Asked after P1–P6 were drawn: let people add the formats the industry already uses, such as PDF and EPUB. They open in the players already drawn; a PDF or a comic gets a page viewer. P1a and P2c now say <code>Add a file</code>.`,
    rules: [
      ['What a phone already has', `<code>Add a file</code> takes, beside an Arke package: <b>EPUB</b> for books; <b>PDF</b> and <b>CBZ</b> for documents, comics and boards; <b>M4B</b>, <b>M4A</b> and <b>MP3</b> for audiobooks and audio; <b>MP4</b> and <b>MOV</b> for video, with an <b>SRT</b> or <b>VTT</b> of the same name picked beside it as its captions. The Add sheet lists them as one line of data (${F('P2c')}). Several files can be chosen at once (${F('P7a')}).`],
      ['Each opens in a player already drawn', `EPUB in the reader (${F('P5e')}) with its own contents and Aa; PDF and CBZ in the page viewer (${F('P7c')}); audio in the audiobook player (${F('P7d')}), an M4B’s chapter markers as its Chapters, else one chapter a file; video in the film player (${F('P3a')}, ${F('P3b')}), its captions from the file’s own text tracks or its SRT or VTT. The Player shows what the file carries and invents nothing: no Text, no Slow push, no picture beyond the file’s own cover.`],
      ['Read before it is added', `A standard file has no manifest to check against, so the Player opens each one before adding it and reads its format, title, author, cover, length or page count and chapters. Each picked file is a row with what was read (${F('P7a')}), or a refusal in one clause: <code>Protected file</code> for DRM — store-locked EPUB, PDF and audio are never opened — <code>Can’t open this file</code>, <code>Not a supported format</code>. The press counts what will be added (<code>Add 3</code>); a refused file is left out, never half-added.`],
      ['Files are not worlds', `Library’s <code>Added</code> holds added worlds and then <b>Files</b>, newest first: the cover or first page, the title, the format with the author, pages or length, and the size (${F('P7b')}). A file has no page of its own: a press opens it in its player, and ⋯ holds Details and Remove. Files join Continue on Home and Added in Downloads (${F('P6a')}). They need no account, are never uploaded, and go only by Remove.`],
      ['A PDF or a comic', `Pages fit the width on the shelves’ theme, scroll as one column and pinch to zoom; a double tap fits the page again (${F('P7c')}). The top holds ⌄, the title, Contents when the file has an outline, and ⋯; the foot the page, <code>3 of 24</code>, with its line. The place is kept on the device. A CBZ reads its pictures in name order as pages.`],
      ['An audio file', `The file’s cover, square and centred on the overlay colours, the title and author under it; a file with no cover shows its title on a plain tile (${F('P7d')}). The transport, speed, sleep and lock screen are the audiobook’s (${F('P5a')}); Chapters lists the file’s markers.`],
      ['Not opened', `MOBI and AZW (Kindle’s own formats), DOCX and plain text are refused as <code>Not a supported format</code>. Converting a file is not the Player’s work.`],
    ],
    next: `Try next: “a video with its SRT” · “Details from ⋯” · “a CBZ comic open”`,
  },
  {
    id: 'p8', status: 'Drawn for the MVP', name: 'Before an account, and a library of files only — first open, nothing added, Home and Library with files, You',
    lead: `The MVP (ArkePlayer <code>docs/mvp.md</code>) plays the person’s own audio, books and films with no account and no Arke worlds. P1–P7 always drew an account and worlds beside files; these are the states without them. Drawn at the owner’s word to start M0, and built on without waiting, as the owner asked.`,
    rules: [
      ['Before an account exists', `No control that needs an account is drawn: not <code>Sign in with Arke</code> on first open (${F('P1a')}), not the picture in Home’s head (${F('P1b')}), not <code>Shared</code> in Library (${F('P1c')}), not the account in You (${F('P6b')}). Each is <b>absent, never disabled</b>. When sign-in arrives those frames return as drawn.`],
      ['First open', `The wordmark over the app’s own picture — bundled with it, since no world exists yet — and one press, <code>Add a file</code>, full width under the thumb (${F('P8a')}). It opens the system’s file picker directly, several files at once: with only one way in, the Add sheet (${F('P2c')}) would be a press that leads to one more press, so it returns when it has a second (<code>Paste a link</code>). <code>+</code> in Library and <code>Add a file</code> on an empty shelf do the same. What was picked is read on the sheet of ${F('P7a')}.`],
      ['Nothing added', `Home, Library and Downloads keep their titles and show one state line, <code>Nothing added</code>, over <code>Add a file</code> (${F('P8b')}). The tabs stay. No picture, no sentence.`],
      ['Library with files only', `With no worlds and no shares there is no <code>All · Shared · Added</code>. The chips are what a person does — <code>All · Listen · Read · Watch</code>, as a world’s groups are — each shown only when a file of its kind exists, and no chips at all when only one kind does (${F('P8c')}). Rows as ${F('P7b')}: cover or first page at <code>52</code>, the title, the format with the author, pages or length, and the size; newest first; <code>+</code> in the head; ⋯ holds <code>Details</code> and <code>Remove</code>.`],
      ['Home with files', `<code>Continue</code> as P1 rule 4, then <b>Added</b>: the newest files, at most <code>10</code>, as <code>120</code> squares with the title and the format; a press opens the file in its player (${F('P8d')}). <code>New</code> and <code>Worlds</code> return with shares and worlds. With files and nothing in progress, Added stands alone.`],
      ['On a Fold', `The rail, and Library’s rows in two columns (${F('P8e')}).`],
      ['You before an account', `<b>Playback</b>: <code>Captions</code>; <b>Storage</b>: <code>On this phone</code> with its size; <b>About</b>: <code>Version</code> and <code>Licences</code> (${F('P8f')}). <code>Text</code>, <code>Slow push</code>, <code>Autoplay next</code>, <code>Wi-Fi only</code> and <code>Adult content</code> return with the Arke audiobooks, micro dramas, shares and adult-marked productions they belong to.`],
      ['Words', `Labels only: Add a file, Nothing added, All, Listen, Read, Watch, Added, Continue, Playback, Captions, Storage, On this phone, About, Version, Licences; sizes, lengths and pages as data.`],
    ],
    next: `Try next: “Details from ⋯” · “Library with one kind only” · “Downloads with files only”`,
  },
  {
    id: 'p9', name: 'Worlds to install — first open, Available, a world before and while it installs, the demo world installed',
    lead: `Asked: let the Player show worlds a person can install; one exists, The Undersong. Drawn with no account, beside P8’s states, and with the demo’s real contents. World import was left out of the MVP (ArkePlayer <code>docs/mvp.md</code>), so whether this is built in it is the owner’s call.`,
    rules: [
      ['What can be installed', `Worlds Arke publishes for anyone, needing no account: today one, <b>The Undersong</b>. The list ships with the app — each world’s name, logline, key art, size, and its package’s address and SHA-256, pinned as the Studio pins its Sample world — so it shows offline and needs no Arke cloud. A new world arrives with an update.`],
      ['Where they are', `First open gains a second press, <code>Install a world</code>, under <code>Add a file</code> (${F('P9a')}). It opens <b>Available</b>, a page of world cards, <code>358 × 190</code>, each with its count and size (${F('P9b')}). Home ends with <code>Available</code>, after Continue and Added, its cards <code>240 × 135</code> (${F('P9g')}); with nothing added it sits under <code>Add a file</code>. A world leaves Available when it is installed and returns when it is removed. With nothing left to install, the press, the page and the section are absent.`],
      ['A world before it is installed', `${F('P1d')}’s hero with one meta line (<code>1 production · 386 MB</code>), the logline, and <code>Install · 386 MB</code> full width, <code>50</code> high (${F('P9c')}). Under it <code>Inside</code>, each production as ${F('P2e')}’s rows — the thumbnail, the title, the kind and length — then <code>Space</code>, the size against what is free. The productions are rows, not tiles: nothing opens before it is installed.`],
      ['Installing', `The press becomes its progress in place (${F('P9d')}): the line, <code>Downloading · 162 MB of 386 MB</code>, then <code>Checking · 140 of 262 files</code>, and <code>Cancel</code>, which deletes what has come. Free space is checked before the first byte. Every file is checked against its manifest, as a package from a file is (P2 rule 6), and nothing plays before the check passes. Leaving the page does not stop it: Home’s card and Downloads show <code>Installing · 42%</code> with the line. It downloads on any network; <code>Wi-Fi only</code> (${F('P6b')}) applies when it returns.`],
      ['Refused in one clause', `As ${F('P2f')}, a sheet over the page (${F('P9e')}): <code>No connection</code>, <code>Download stopped</code>, <code>Needs 386 MB · 210 MB free</code>, <code>3 files do not match</code>, with the world and its size under it, then <code>Try again</code> and <code>Close</code>. Nothing partial is kept.`],
      ['Installed', `The page becomes ${F('P1d')}’s (${F('P9f')}): the meta line <code>Installed · 1 production · 386 MB</code>, the productions grouped by what a person does, and ⋯ with <code>Details</code> and <code>Remove</code>. A world with <b>one production</b> shows it at the full width, <code>358</code>, not as a <code>160</code> tile. The world joins Library above the files, under <code>All</code> (${F('P7b')}), and Home’s <code>Worlds</code>. It is the person’s, like a package from a file: it needs no account and goes only by Remove, which deletes it and its places and returns it to Available.`],
      ['The Undersong', `The demo is The Undersong as Arke publishes it: <b>The Ledger of Nights</b>, sixteen chapters with the narration of twelve, about <code>3 h 49 m</code>: the Studio’s own EPUB and M4B, published on 20 October 2026. It is one production under <code>Listen</code>, its kind line <code>Audiobook · Book</code> (P1 rule 6): <code>Read</code> opens all sixteen chapters, and Chapters lists the twelve that are narrated (P5 rule 2). The video pilot is unfinished and is not in it. The Player installs it as a <b>world package</b> (ADR 0005), never as the Studio’s Sample world — the 1.6 GB editable world the Studio downloads (ArkeStudio #1949) — which is a world’s source (P1 rule 1). Its package is 182 MB; the frames’ sizes and file counts are samples.`],
      ['On a Fold', `The rail; the key art across the page, <code>400</code> high; the words and <code>Install</code>, <code>320</code> wide, at the left; Inside and Space in a column <code>640</code> wide (${F('P9h')}).`],
      ['Words', `Labels only: Install a world, Available, Install, Inside, Space, Downloading, Checking, Installing, Installed, Cancel, Try again, Close, No connection, Download stopped; counts, sizes and times as data.`],
    ],
    next: `Try next: “Available with several worlds” · “a world installing, seen from Home” · “Details from ⋯”`,
  },
  {
    id: 'p10', date: '21 October 2026', name: 'A world already in Library — another edition replaces it, the same one is refused',
    lead: `SPEC-058 R-21. A world package added from a file (P2c–P2f), such as one made by the Studio’s Export → Arke Player (Studio <a class="dv-oid" href="../../ArkeStudio/design-system/Arke%20Studio.dc.html#t233">233</a>), may be of a world the library already holds.`,
    rules: [
      ['Another edition', `When the package is of a world in Library and its edition differs, Ready (${F('P2e')}) becomes Replace (${F('P10a')}): the package’s line as ever (<code>made 21 Oct 2026 · 1 production · 228 MB</code>), Inside, then <code>In Library</code> with the installed edition’s date and size, and <code>Space</code> as the difference (<code>+46 MB of 41 GB free</code>). The presses are <code>Replace</code> and <code>Cancel</code>. Newer or older, the two dates say which; nothing warns.`],
      ['What an edition is', `Two packages are the same edition when their <code>edition</code> labels and every file’s SHA-256 agree. Anything else is another edition, so a package made again under the same label is still offered as Replace.`],
      ['Replacing keeps the places', `The new edition is checked in full first (${F('P2d')}). The old files go only once the new are in place, so Cancel or a refusal leaves Library as it was. Places are kept by chapter: a narration’s place by its chapter id and time, a book’s by its chapter where that chapter still exists, else the production’s start. Continue keeps its card; the world’s card, page and size follow the new edition.`],
      ['The same edition', `Refused in one clause (${F('P10b')}): <code>Already in Library</code>, with the world and its edition under it, then <code>Open</code> (the world’s page) and <code>Close</code>. The copy is deleted.`],
      ['Words', `Labels only: Replace, Cancel, In Library, Space, Already in Library, Open, Close; dates and sizes as data.`],
    ],
    next: `Try next: “a newer edition on Available after an app update” · “an older edition” · “Replace while its audiobook plays”`,
  },
  {
    id: 'p11', date: '22 October 2026', name: 'Worlds to explore — the Worlds tab, a world’s characters, places and lore, and what waits for a chapter',
    lead: `Asked: a Worlds section where people explore worlds and their productions, and read about the characters and some of the lore, starting with the worlds Arke makes available. Approved as drawn by the owner on 22 October 2026; to be specified in SPEC-059. The guide is what a world’s author makes public in the Studio (Studio <a class="dv-oid" href="${STUDIO}#t234">234</a>).`,
    rules: [
      ['Worlds is a tab', `The tabs become five, <code>Home · Worlds · Library · Downloads · You</code>, Worlds second (P1 rule 3 amended); on a Fold, the rail (${F('P11i')}). Worlds (${F('P11a')}) lists <b>In Library</b>, then <b>Available</b>, as cards <code>358 × 190</code>, each meta line its productions, characters and, before install, size. It takes the place of ${F('P9b')}’s Available page: first open’s <code>Install a world</code> opens it, and Home keeps its <code>Available</code> section (${F('P9g')}).`],
      ['Arke’s worlds, not yet a directory', `The worlds are the ones Arke makes available: a list that ships with the app, each package pinned by its SHA-256 (P9 rule 1), growing with each update as more worlds are made. A directory anyone publishes to needs the Arke cloud — accounts, hosting, moderation, takedown, rights and ratings — and is not drawn.`],
      ['A world’s guide', `<b>Characters</b>, <b>Places</b> and <b>Lore</b>, as the author made them public. The guide is small and pinned in the list on its own, so a world can be explored before it is installed (${F('P11b')}): it is fetched when the page first opens and kept. Installing brings it in the package. Nothing in it is a world’s source (P1 rule 1): no sheets, notes, prompts or open questions.`],
      ['A world’s page', `The hero; then the productions — <code>Install</code> and Inside before (${F('P11b')}), the groups after (${F('P11c')}); then Characters as cards <code>120</code> wide, <code>4:5</code>, name and role; Places as ${F('P1d')}’s <code>160</code> tiles; Lore as rows, the kind over the title. Each head carries its count. A section with nothing public is not drawn. A character with no portrait shows initials.`],
      ['A character', `${F('P11d')}: the portrait as the hero, the name, <code>role · world</code>, and <code>Voice</code> with its length — a line from a production in their voice, chosen by the author. Then the sections made public, in the author’s order and words, under their own headings (<code>Essence</code>, <code>Appearance</code>), and <code>With</code>: the characters and places linked, each opening its page.`],
      ['A place, a lore entry', `A place (${F('P11e')}): the picture, the name, <code>Place · world</code>, its public sections, and <code>Here</code>, the characters linked. Lore (${F('P11f')}): rows under the chips <code>All · Lore · Rules · Timeline</code>; an entry (${F('P11g')}) is its kind, its title in <code>text-3xl</code>, the author’s text, and <code>With</code>.`],
      ['What waits for a chapter', `Each character, place, lore entry and section is public from the start or <b>after a chapter</b> of a production. Until this phone’s place in that production — read or heard — passes the chapter, it is drawn as <code>After Chapter 6</code> with the hidden mark and <code>Reveal</code>: a row in a list, a card with no portrait among the characters, a row in place of a section. Reveal asks once (${F('P11h')}): the chapter, the production and where you are, then <code>Reveal</code> or <code>Not now</code>. What is revealed or reached stays shown on this phone.`],
      ['On a Fold', `The rail; characters <code>160</code> wide, places <code>280</code>; lore in two columns (${F('P11i')}).`],
      ['Words', `Labels only: Worlds, In Library, Available, Characters, Places, Lore, Rules, Timeline, Voice, With, Here, Reveal, Not now, After Chapter N; counts, sizes and lengths as data. The sections’ headings and texts are the author’s.`],
    ],
    next: `Try next: “a world with no guide” · “a world’s guide offline, never fetched” · “a character in two productions”`,
  },
  {
    id: 'p12', date: '22 October 2026', name: 'A world’s newer edition — seen on Worlds and the world’s page, updated in place, its places kept',
    lead: `Asked: when a world’s audiobook is updated in the Studio, does the Player see it and offer the download? Today only a package added from a file does (${F('P10a')}); a world installed from Arke’s list never shows a newer edition, because the list ships with the app and names no edition. The sample: The Undersong installed at its 20 October edition, Arke’s list naming the 22 October one, made by the Studio’s Export → Arke Player (Studio <a class="dv-oid" href="${STUDIO}#t233">233</a>). Approved as drawn by the owner on 22 October 2026, with calls 8 and 9.`,
    rules: [
      ['Arke’s list, fetched', `The list of Arke’s worlds (P9 rule 1) is also kept at one Arke address and fetched over HTTPS when Worlds or a world’s page opens, at most once a day. Each entry names its <b>edition</b>: the label, and its package’s address, length and SHA-256, pinned as before. The list in the app stays as the floor, so Worlds shows offline and never goes back to an older list. A world’s guide alone (P11 rule 3) is fetched again when its pin changes.`],
      ['A newer edition', `An installed world whose edition in the list is not the one installed (P10 rule 2) has an update. Its card on Worlds carries <code>Update</code> (${F('P12a')}). A world added from a file has no entry in the list: a newer package of it is added from a file, as ${F('P10a')}.`],
      ['On the world’s page', `<code>Update · 228 MB</code> under the logline, full width, as Install (${F('P12b')}); the meta line keeps the installed edition, <code>Installed · 20 Oct 2026 · 182 MB</code>. Under the hero, <code>New edition</code> with its date and size, and <code>Space</code> as the difference (<code>+46 MB of 41 GB free</code>).`],
      ['Updating', `As installing (P9 rule 4): the press becomes its progress in place, <code>Downloading · 120 MB of 228 MB</code>, then <code>Checking</code>, and <code>Cancel</code> (${F('P12c')}); Downloads lists it under <b>Worlds</b>, <code>Updating · 53%</code> (${F('P12e')}). The installed edition stays and plays until the new one is checked in full, then gives way to it as P10 rule 3: the old files go once the new are in place, and places are kept by chapter. While something of the world plays, the swap waits for it to stop.`],
      ['Updated', `The meta line takes the new edition, <code>Installed · 22 Oct 2026 · 228 MB</code>, and the press and the New edition rows go (${F('P12d')}). Continue keeps its card and its place; the productions show what the new edition holds.`],
      ['Pressed, not automatic', `An update downloads only when <code>Update</code> is pressed: a world is the person’s (P9 rule 6), and an edition can change what they are partway through. <code>Wi-Fi only</code> (${F('P6b')}) applies to it as to a download.`],
      ['Refused in one clause', `As ${F('P9e')} (${F('P12f')}): <code>Needs 46 MB · 20 MB free</code>, <code>No connection</code>, <code>Download stopped</code>, <code>1 file does not match</code>, with the world and the new edition’s date, then <code>Try again</code> and <code>Close</code>. The installed edition is untouched.`],
      ['Words', `Labels only: Update, New edition, Space, Downloading, Checking, Updating, Cancel, Try again, Close; dates, sizes and counts as data.`],
    ],
    next: `Try next: “an update while its audiobook plays” · “a world gone from Arke’s list” · “Update from Home’s Continue”`,
  },
  {
    id: 'p13', date: '22 October 2026', status: 'Implemented from owner request', name: 'Check for world updates now',
    lead: `Requested by the owner: check for world updates immediately, without the daily wait or restarting. This extends the Worlds header of ${F('P11a')} and keeps the update behavior of ${F('P12')}.`,
    rules: [
      ['One press in Worlds', `A round refresh press at the right of the Worlds header, using the existing shelf control, with a minimum <code>44 × 44</code> target and tooltip/accessibility label <code>Check for updates</code> (${F('P13a')}). The same header is used on phone, tablet and desktop (${F('P13e')}, ${F('P13f')}); keyboard activation works. No new menu or screen.`],
      ['Immediate, once', `Pressing checks the hosted catalogue even inside the daily interval. An automatic check already in progress finishes first; repeated presses never start overlapping requests. Automatic checks retain P12’s daily interval. Manual checks do not download a world.`],
      ['While checking', `The icon becomes a spinner and the press is disabled. A short live status under the header says <code>Checking for updates</code> (${F('P13b')}). Existing worlds, scrolling and playback remain available.`],
      ['The result', `On success the status says <code>Checked</code>, and every screen uses the newest catalogue immediately. Existing update tags and Update presses indicate which worlds have a newer edition (${F('P13c')}). Checked means the list was fetched, not that installed worlds were replaced. An older remote list never replaces the newer local or shipped list.`],
      ['Retry', `Offline, a timeout, a malformed list or a save failure says <code>Couldn’t check for updates</code> (${F('P13d')}). Keep the current list and re-enable the same press for immediate retry; never show Checked for a failed request.`],
      ['Reading and access', `Use existing theme and type tokens. Status wraps at large text sizes and is announced as a live region; controls remain reachable at 200% text, in light and dark themes. No captions under cards, layout redesign or automatic world downloads.`],
    ],
    next: `The daily background check and explicit manual check share the same catalogue cache.`,
  },
  {
    id: 'p14', date: '23 October 2026', name: 'A picture made for the screen — Wide for a tablet, Tall for a phone',
    lead: `The owner, on 23 October 2026: on a phone the listen screen letterboxes a wide picture into the top 62% (${F('P5a')}), and the picture should fill the screen. The Studio now makes a moment’s picture in up to two shapes, Wide and Tall, the Tall made from the Wide (Studio <a class="dv-oid" href="${STUDIO}#t235">235</a>), and the package carries both. This turn draws only what changes: a phone in portrait on a moment with a Tall picture, Text off (${F('P14a')}) and on (${F('P14b')}). The sample is a real Tall picture: The Undersong’s Maren at the ledger, made at 9:16 from its 16:9 picture with the Wide one as the reference, the same face, room, ledger, lamp and window. Approved as drawn by the owner on 23 October 2026, with Studio 235.`,
    rules: [
      ['Two shapes, one moment', `A moment’s picture comes in up to two shapes: <b>Wide</b>, 16:9, and <b>Tall</b>, 9:16. Both share the moment’s one time and one hold; the Tall is the same picture composed for a phone, never a different moment. The package carries both shapes.`],
      ['A phone, upright', `A phone in portrait shows the <b>Tall</b> picture over the whole screen when the moment has one (${F('P14a')}), under the top bar, Slow push and the transport, on ${F('P5a')}’s two scrims. A phone is narrower than 9:16, so the Tall picture covers it about its focus and loses a sliver at each side, never a band top or bottom. A moment with no Tall picture shows its Wide one as ${F('P5a')} does: whole, in the top 62%.`],
      ['Everywhere else, Wide', `A tablet, a Fold (${F('P6f')}) and a phone turned always show the <b>Wide</b> picture, as today.`],
      ['Text on', `With Text on, the words sit over the lower picture where ${F('P5a')} sets them, and the foot scrim deepens under them: <code>92%</code> of the media background to <code>240</code> px from the foot, fading out by <code>600</code> (${F('P14b')}), so they read on a bright picture as on a dark one. With Text off the scrim is ${F('P5a')}’s.`],
      ['Moving between pictures', `The one-second crossfade and Slow push work as before, on whichever shape is shown, about the picture’s focus. Turning the phone mid-hold swaps the shape at once, at the same place in the hold.`],
      ['Nothing else changes', `A package with no Tall pictures plays exactly as today. No setting, no press and no label is added to the Player: the shape follows the screen.`],
    ],
    next: `Try next: “a chapter with Tall pictures for some moments only” · “a Tall picture with motion” · “the phone turned mid-hold”`,
  },
  {
    id: 'p15', date: '24 October 2026', status: 'Approved', name: 'Discover — what you can get, a world’s kinds of production, and chapters released over time',
    lead: `The owner, on 24 October 2026: should Worlds become Discover, showing worlds, their productions and other things made for them; and a world may release its story a chapter at a time to bring its audience back, so how does the Player show that? And: a world’s page with more than one kind of production, a micro drama among them. Drawn on the five calls approved that day: Discover is what you can get and Library what you have; Discover leads with productions and new chapters; teasers are the author’s choice; a new chapter comes on its own over Wi-Fi; a notification is the phone’s own, per world. Legend of Dumah, The Red Quiet and Embers of the Fallen are Arke’s worlds on Available; The Undersong’s six productions are ${F('P1d')}’s sample. Chapter dates, schedules and episode counts are samples. The author’s half — releasing a chapter and choosing teasers — is Studio <a class="dv-oid" href="${STUDIO}#t236">236</a>.`,
    rules: [
      ['Discover is a tab', `The tabs become <code>Home · Discover · Library · Downloads · You</code>: Discover takes Worlds’ place (P11 rule 1 amended) and is what Arke offers, installed or not (${F('P15a')}). <b>Library</b> is what is on the phone: installed worlds as cards first, each with <code>New</code> or <code>Update</code>, then added files as ${F('P8')}, under Discover’s chips (${F('P15h')}). A world’s page is one page from either. ${F('P13a')}’s Check for updates press moves to Discover’s header.`],
      ['Stories first', `Discover’s chips are <code>All · Listen · Watch · Play · Read</code>; then <b>New chapters</b>, <b>Stories</b>, <b>Teasers</b> and <b>Worlds</b> (${F('P15a')}, ${F('P15b')}). A production’s tile names its kind and its world, and opens the world’s page at that production. An installed world stays in Discover; its meta line says <code>In Library</code>. On a Fold, the rail and the same rows, wider (${F('P15l')}).`],
      ['A world’s kinds', `A world’s page groups its productions by how they are taken (${F('P15c')}, ${F('P15d')}): <b>Listen</b> (audiobook, audio drama), <b>Watch</b> (film, series, micro drama), <b>Play</b> (interactive movie, visual novel), <b>Read</b> (book). A production both heard and read sits under Listen. Each head carries its count; a group with nothing is not drawn. A micro drama takes the same tile as a film; its upright episodes are on its own page (${F('P15f')}). The guide (${F('P11c')}) follows the groups.`],
      ['Teasers', `What the author picks in the Studio’s Publish, up to six a world: a character or place public from the start, never one that waits for a chapter (P11 rule 7); a picture; or a clip of up to 30 seconds. A picture or clip shows to anyone whatever its chapter, which is the author’s call (Studio 236 rule 4). A character or place opens its page (${F('P11d')}, ${F('P11e')}); a picture opens full screen; a clip plays muted in the row and with sound when opened. Each leads to its world.`],
      ['A world in parts', `A world’s package becomes its <b>base</b> — the guide, the key art and each production as first published — and one <b>part</b> per release, each pinned in Arke’s list by its SHA-256 as a package is (P9 rule 1). Install fetches the base and every part.`],
      ['A new chapter arrives', `When the list names a part an installed world lacks, the phone fetches it on its own and adds it beside what is there: nothing being played changes. <code>Wi-Fi only</code> (${F('P6b')}) applies; Downloads lists it under <b>Worlds</b> (${F('P15k')}). A new edition (${F('P12b')}) still waits for Update (P12 rule 6 holds for editions; parts only add).`],
      ['New', `A chapter or episode that arrived since its production was last opened carries <code>New</code>: on its row (${F('P15e')}), its tile, its world’s card in Library, and on Continue once the one before it is finished (${F('P15g')}). Opening it clears it. Discover’s New chapters is every world’s releases of the last 14 days, newest first; Home’s is the installed worlds’ only.`],
      ['The author’s schedule', `A production may carry its author’s schedule: a day, <code>Fridays</code>, and the next date. It is drawn as written — under the meta, and as a dashed last row, <code>Chapter 4 · 30 Oct</code> (${F('P15e')}), or <code>Next 26 Oct</code> (${F('P15f')}). A date that passes with no release drops it, so nothing shown is stale.`],
      ['Notify', `Per world, off until turned on in the world’s ⋯ (${F('P15j')}); the first one asks the phone’s permission. It comes from the phone’s daily check of Arke’s list (P12 rule 1), so up to a day after the release, names the world, the chapter and the production, and opens the production (${F('P15i')}). No account and no server.`],
      ['One tile', `Every row in Discover, Home and a world’s page is one tile, <code>16:9</code>, <code>240</code> wide on a phone and <code>300</code> on a Fold — the width of a world’s card in a row (${F('P15g')}, ${F('P15l')}) — whatever it holds: a chapter, a production, a teaser, a character (${F('P15a')}, ${F('P15c')}, ${F('P15d')}). Mixed sizes and shapes in a page’s rows look unkempt (the owner, 24 October 2026). A character with no portrait shows its initials; one that waits for a chapter is a quiet tile, <code>After Chapter 9</code>. This replaces P11 rule 2’s <code>120</code> cards and <code>160</code> tiles on a world’s page. A world with one production still shows it at the full width (${F('P9f')}).`],
      ['Words', `Labels only: Discover, New chapters, Stories, Teasers, Worlds, New, Notify, Waiting, Next; days, dates, counts and sizes as data.`],
    ],
    next: `Try next: “install one production of a world” · “a chapter arriving while the one before plays” · “a release taken back”`,
  },
  {
    id: 'p16', date: '24 October 2026', status: 'Approved with calls 14, 15 and 16', name: 'Rows of different sizes — a feature, posters, wide tiles and a world’s band',
    lead: `The owner, on 24 October 2026, with Netflix’s Home on a phone and a tablet: the boxes of different sizes are great, with emphasis on some titles. Netflix keeps each row one size and changes the size from row to row. P15’s first draw mixed sizes inside a row, which is what looked unkempt, and P15 rule 10 answered it with one tile everywhere; P16 keeps every row tidy and gives the page its emphasis back. The samples are P15’s. Na Love or Juju is Arke’s world as published; its poster is the book cover in the middle of its published cover. Arke’s covers are wide today, so a poster’s Tall cover is call 14. Approved the same day with calls 14 and 15 (the owner: upright is the industry’s norm, and a page can mix and match), and the pill asked to be seen: ${F('P16h')} – ${F('P16j')}. Seeing it, the owner chose the pill (call 16).`,
    rules: [
      ['A row is one size', `Each row is one size and one shape, whatever it holds; a page mixes rows, and the size says how much a row matters (${F('P16a')} – ${F('P16g')}). Five sizes, phone · Fold: the <b>feature</b>; <b>posters</b>, 2:3, <code>172 × 258</code> · <code>260 × 390</code>; <b>wide tiles</b>, 16:9, <code>240 × 135</code> · <code>300 × 169</code>; <b>small posters</b>, 2:3, <code>112 × 168</code> · <code>160 × 240</code>; the <b>band</b>. This replaces P15 rule 10. Home keeps its Continue cards (P1 rule 4) and Library its world cards.`],
      ['The feature', `Discover opens on one production (${F('P16a')}): <code>358 × 476</code> on a phone, upright, from its Tall cover; <code>848 × 424</code> on a Fold, from its Wide cover, the words at the left (${F('P16f')}). <code>New</code> and the chapter, the title, the kind and world, and one press: <code>Install · 1.9 GB</code>, or <code>Play · Chapter 24</code> once the world is installed. The card opens the world’s page at the production. The feature is drawn under <code>All</code> only.`],
      ['Posters', `2:3, from the production’s Tall cover: Stories (${F('P16b')}) and a world’s Listen and Read (${F('P16d')}), where audiobooks and books sit. A production without a Tall shows its Wide cover whole over its own blur — Whispers from the Void, Undertow — never cut.`],
      ['Wide tiles', `16:9 with the title and kind under, as P15: New chapters, a world’s Watch and Play, and Places (${F('P16b')}, ${F('P16e')}). A chapter, a film or a place is a moment, and a moment is made wide.`],
      ['Small posters', `2:3: Teasers (${F('P16c')}) and a world’s Characters (${F('P16e')}). A character shows its portrait uncut, where P15 cut faces to 16:9. A picture or clip shows its Tall if it has one (P14), else its Wide over its blur. No portrait shows initials; one that waits shows <code>After Chapter 9</code>.`],
      ['The band', `One world across the page (${F('P16c')}, ${F('P16g')}): its key art blurred behind, on the media colours whatever the theme; the key art small, the name, productions and size, <code>Install</code>, the logline in two lines; then its productions and characters as small posters. One a page, after Teasers.`],
      ['Which feature, which band', `Named in Arke’s list, one line each (call 15). With neither named, the feature is the newest release and the band the newest world.`],
      ['Words', `Labels only: the title and kind under every tile and poster, the feature’s on its picture; Install, Play, New and chapters as data.`],
      ['The pill', `The tabs become a pill floating over the page (call 16; ${F('P16h')} – ${F('P16j')}), in place of P1 rule 3’s bar and ${F('P6e')}’s rail. It holds the same five tabs, <code>358 × 64</code> on a phone and <code>520</code> wide on a Fold, <code>24</code> above the foot, with the current tab in a capsule. The page runs under it to the foot and fades into the page’s ground. A playing chapter’s dock floats above it (${F('P16i')}). On a Fold, the page takes the full width (${F('P16j')}). Frames drawn before P16h keep the bar as they were drawn; the pill is what is built.`],
    ],
    next: `Try next: “Discover under Listen” · “the feature for an installed world” · “Home with a feature”`,
  },
  {
    id: 'p17', date: '24 October 2026', status: 'Approved', name: 'Music — an album, a single, a soundtrack, within a world',
    lead: `The owner, on 24 October 2026: if music is supported as a production, or just an artifact, how is it shown within a world? Drawn on the recommendations approved the same day (call 17): music is a production, it has its own group with square tiles, it plays in the audio player with a track list, it is tied to where it is heard and whose theme it is, and a song can be a teaser. The author’s half — a Music production made from Bench takes, its Theme and Song teaser in the Guide, and its export — is Studio <a class="dv-oid" href="${STUDIO}#t238">238</a>. The tracks, lengths and lyrics are samples; the covers are pictures already in this master. Approved as drawn the same day, with Studio 238 and its composer, track editor and sequence, and calls 17 – 20.`,
    rules: [
      ['Music is a production', `A world’s music is published as a production of one of three kinds: <b>Album</b>, several tracks; <b>Single</b>, one; <b>Soundtrack</b>, several, for one of the world’s productions (<code>Soundtrack · The Bell Watch</code>). A song is never a loose take: as a production it has a cover, a size and a place in Arke’s list, and installs and updates with its world (call 17).`],
      ['Its own group', `A world’s page gains <b>Music</b> after Listen: <code>Listen · Music · Watch · Play · Read</code>, with its count (${F('P17a')}). Discover gains a Music row after Stories (${F('P17b')}). Under the chips it sits with <code>Listen</code>: what is heard. Home’s Continue never holds a song.`],
      ['Square', `A music production’s tile is square, <code>160</code> on a phone and <code>200</code> on a Fold, its title and kind under it (P16 rule 1: a row is one shape). Its cover is made 1:1, at <code>1024 × 1024</code>, the fourth picture shape beside 2:3, 9:16 and 16:9 (call 18). It comes with the list as any picture does (SPEC-058 R-63).`],
      ['An album’s page', `The cover over its own blur, the title, <code>Album · The Undersong · 9 tracks · 34 min</code>, <code>Play all</code> and <code>Shuffle</code> (${F('P17c')}). Then the tracks, numbered, each with its length and at most one line: whose theme it is, or where it is heard. The one playing shows bars in place of its number. On a Fold the cover sits beside the title and the tracks run in two columns (${F('P17h')}). Under them, <code>More from</code> the world: its other music.`],
      ['Playing', `The audio player, with the cover where the moment’s picture would be, over its own blur (${F('P17d')}): shuffle, previous, play, next, repeat; then <code>Lyrics</code> when the track has words, <code>Tracks</code>, and where it is heard, <code>Chapter 9</code>, which opens the chapter where it plays. The dock and the lock screen show the track and its album, with Next where a chapter has back 15 (${F('P17c')}). A song keeps no place: it starts from its beginning, and Play all from the first track.`],
      ['Lyrics', `As written, over the dimmed cover, scrolled by hand (${F('P17e')}); not timed to the song (call 19).`],
      ['Heard in, and Theme', `A track may be heard in a production: its row says so (<code>Heard in · The Ledger of Nights, Chapter 8</code>), the production’s page lists its <b>Music</b>, and a chapter that holds a song carries a note (${F('P17g')}). A character or place may have one track as its <b>Theme</b>, played from its page under its Voice (${F('P17f')}). Both are what the author set in the Studio; the Player only reads them.`],
      ['A song as a teaser', `A Song teaser is a track’s excerpt of at most 30 seconds, in the Teasers row as a small poster: its square cover whole over its blur, with a note (${F('P17b')}). It plays with sound when opened; nothing plays in the row.`],
      ['Words', `Labels only: Music, Album, Single, Soundtrack, Play all, Shuffle, Lyrics, Tracks, Theme, Heard in; tracks, lengths and minutes as data.`],
    ],
    next: `Try next: “a soundtrack’s page from its micro drama” · “music while a chapter is paused” · “a world whose only production is an album”`,
  },
  {
    id: 'p18', date: '28 October 2026', status: 'Approved', name: 'Interactive stories — at their own shape, remembering choices, as packages',
    lead: `The owner, on 28 October 2026: have we designed what interactive stories look like on the Player? P4 had, on 20 October, before the pill, the rows, picture shapes and remembered choices, and it cropped a 16:9 movie to fill an upright phone where P3a letterboxes a film. Since then the Studio’s stories remember (SPEC-063, Studio <a class="dv-oid" href="${STUDIO}#t240">240</a>): choices set named facts, other choices open or close on them, scenes play differently, and a route replays. The Studio exports a story only as a web folder, and SPEC-063 leaves an Arke Player format out of scope. P18 brings P4 up to date and proposes how a story reaches a phone (calls 21 – 24). The production it is for is The Red Quiet: First Contact: 202 scene variants, 201 choices, five families of ending. The samples stay The Undersong’s, with Ring Once a 9:16 movie of its own; choice labels and reasons are samples of the author’s words. Approved as drawn the same day, with calls 21 – 24.`,
    rules: [
      ['At its own shape', `A story plays at the shape it was made in, and nothing is cropped to fit. A 16:9 movie held upright sits whole a little above the middle, where P3a holds a film, and at a choice the choices take the controls’ place under it (${F('P18b')}). Turned, it fills the height with the choices over its foot (${F('P18c')}); on a Fold it runs the width with the choices under it (${F('P18h')}). A 9:16 movie fills the phone (${F('P18d')}). This withdraws P4a’s full-screen crop.`],
      ['The choices', `Full width where the thumb is, <code>58</code> high, in the author’s order, numbered, the first in focus, <code>Replay scene</code> under them. Two sit side by side only where both labels fit whole: turned, and on a Fold. Three or more are always one list, as in the Studio’s player. Nothing counts down.`],
      ['A closed choice', `A choice can close because of an earlier one: the key was left at the weigh house, so <code>Use the tenth key</code> can’t be taken. Such a choice is hidden unless the author wrote a reason for it. With a reason, it stays in its place, dashed and dimmed, with a dash for its number and the reason under its label (${F('P18d')}; SPEC-063). The open choices are numbered 1, 2, 3 around it. The facts themselves are never shown: what a story remembers shows only in what it plays and offers (call 23).`],
      ['The route', `P4b’s glass sheet, with stills at the story’s shape: <code>96 × 54</code> for 16:9, <code>40 × 72</code> for 9:16 (${F('P18e')}). A long route folds its middle into one row, <code>5 more scenes</code>, which opens it. <code>Choose again</code> goes back to that choice and takes back everything after it, what the story remembers included. <code>Start over</code> takes back all of it. A production’s page shows the same route under <code>Continue</code> (${F('P18a')}).`],
      ['A visual novel', `P4d’s box, <code>Auto</code> and <code>Log</code>, on each beat’s picture at its shape. Upright, a beat’s Tall picture fills the phone when it has one (${F('P18f')}), as an audiobook’s moments do. Without one, the wide picture sits whole at the top and the box under it (${F('P18g')}). At a choice the last line stays, with the choices under it.`],
      ['Where you are', `The device keeps the route: the choices taken, from which what the story remembers follows, and a place in the scene. <code>Continue</code> replays it on the edition installed. If an update changes the story so the route can no longer be replayed, <code>Continue</code> gives way to <code>Start again</code>.`],
      ['How it arrives', `A story is a production package (SPEC-058 R-68), published beside its world’s edition, so neither the world’s audiobook nor 202 scene variants are downloaded for the other. It holds one story document, compiled from the Studio’s routing: scenes, choices, facts, conditions, effects and what plays when. Its clips or pictures come with it. A Player that can’t read that version of the document shows the story with <code>Update app</code> and never plays part of it (calls 21, 22).`],
      ['Words', `Labels only: Continue, Your route, Route, Choose again, Start over, Start again, Replay scene, Auto, Log, more scenes. Choice labels and their reasons are the author’s.`],
    ],
    next: `Try next: “the endings you have reached” · “a story whose update can’t replay your route” · “three choices turned”`,
  },
  {
    id: 'p19', date: '28 October 2026', status: 'Approved', name: 'A story plays itself — no tap moves on, and a choice is two or more',
    lead: `The owner, on 28 October 2026: “Whenever an option is provided to the user it must be at least two as a minimum”, and an interactive story “should play like a video, going through the video with optional narration and only pausing when an option is displayed. There should not be a need to tap to move forward.” The design said the opposite, and the build followed it: P4d’s tap moved on, P18’s <code>Auto</code> was a toggle, off by default, and nothing kept a lone option off the screen, so First Contact showed <code>1 Several weeks later</code> as its only button. P19 makes a story play itself and stop only for a real choice (calls 25 – 27). Rules 1 – 5 are shared with a Studio turn drawn the same day. The samples are P18’s, with The Red Quiet’s First Contact as a story without voices; its lines and its choice are the author’s.`,
    rules: [
      ['A story plays itself', `A visual novel moves from beat to beat on its own: a voiced beat when its voice ends, an unvoiced beat after time to read it, <code>1.5 s</code> + <code>45 ms</code> per character, as shipped (${F('P19a')}). An interactive movie already plays its clips (${F('P19f')}). A story opens playing.`],
      ['No tap moves on', `A tap shows or hides the controls, as a film’s do: Play/Pause, Back (the previous beat), Log, and Narration where the story has voices (${F('P19b')}). <code>Auto</code> is gone; Play/Pause replaces it. This withdraws P4d’s “a tap anywhere moves on”, P18’s <code>Auto</code>, and the › in the box (${F('P4d')}, ${F('P18f')}).`],
      ['It stops only for a choice of two or more', `Every option shown is one of at least two (${F('P19e')}). A closed choice shown with its reason counts as one of the two.`],
      ['A lone option is never shown', `When only one way on is open, the story plays straight through to where it leads, with no pause and no label. First Contact’s <code>Several weeks later</code> was one: <code>Open hands</code> now runs straight into <code>The last ordinary shift</code>, whose first line already says it.`],
      ['Narration is optional', `When a story carries voices, Narration is on, and the listener can turn it off. With it off, or in a story without voices, each beat holds for its reading time. The control shows only when the story has voices (${F('P19b')}; none in ${F('P19d')}).`],
      ['The controls', `Over two scrims, as P3a’s (${F('P19b')}): ⌄, the story and its scene, and ⋯ (Route, Start over); <code>Narration</code> as a labelled switch under them; then <code>Back</code>, Play/Pause <code>64</code> and <code>Log</code>, Play on the centre line, with the scene’s beats over them where a film’s scrubber sits. On a Tall picture they sit above the box; on a wide one, at the foot, where a film’s do (${F('P19c')}). While playing they rest after <code>2.5s</code>; paused, they stay. The box is the story, not a control, and never moves when the controls come and go (${F('P19a')}, ${F('P19b')}). Turned, the controls sit over the picture and the box over its foot (${F('P19g')}).`],
      ['At a choice', `The story stops with the last line in the box and the choices where the transport was, <code>Replay scene</code> and <code>Log</code> under them; the top stays while it waits (${F('P19e')}). The choices are P18’s: numbered, the first in focus, nothing counting down.`],
      ['An interactive movie', `Its controls are a film’s (${F('P3a')}): the scene’s scrubber and time, back <code>10</code>, Play/Pause, forward <code>10</code>, with captions and the route at the top (${F('P19f')}). A movie has no beats, Log or Narration. At a choice of two or more it stops as ${F('P18b')} draws.`],
      ['The route', `A lone way leaves no row: the two scenes it joins sit one after the other, and <code>Choose again</code> belongs only to a choice of two or more (${F('P19h')}). The lone way is still taken, with whatever it sets, so the route replays. An ending’s choices (${F('P4c')}) and a production’s <code>Your route</code> (${F('P18a')}) leave it out too.`],
      ['Words', `Labels only: Narration, Back, Log, Replay scene, Route, Start over. <code>Auto</code> is gone. Lines and choice labels are the author’s.`],
    ],
    next: `Try next: “Narration off” · “one open choice beside a closed one” · “a voiced story on a Fold”`,
  },
  {
    id: 'p20', date: '29 October 2026', status: 'Approved', name: 'A graphic novel — read a page at a time, the way its book turns',
    lead: `Approved by the owner on 29 October 2026 (“Approved, build the player”), calls 28 – 31. The owner, on 29 October 2026, after Studio <a class="dv-oid" href="${STUDIO}#t247">247</a> was approved: “Do the Player side.” A graphic novel (SPEC-064) is a story told in pages: each page one picture with its lettering in it, read in order, left to right, right to left as manga, or as one tall scroll for a webtoon. The Studio exports it as CBZ, PDF and EPUB; P20 is how it reaches a phone and is read there (calls 28 – 31). The sample is The Undersong’s Low Water, drawn, two chapters of 24 pages, and The Lantern Road for Scroll. Its page is composed from the master’s pictures with lettering laid over them; it stands for a generated page.`,
    rules: [
      ['How it arrives', `A graphic novel is a production package of its own, beside its world’s edition, as a story is (${F('P18')}): world package schema 7, one comic document listing the chapters and their pages in reading order, with the book’s reading direction, page shape and language, and each page’s picture with its alt text. Arke’s list pins it under the production’s <code>comic</code>, never <code>package</code> or <code>story</code>, so a Player that cannot read it never fetches it (call 28).`],
      ['Its page', `A world’s graphic novel has a page as a story’s does (${F('P20a')}): its picture, <code>Graphic novel · 24 pages</code>, <code>Continue</code> with the page you are on, the size, and its chapters as page tiles, 2:3. Discover shows it as any production.`],
      ['A page whole', `A page is read whole, at its own shape, on black, with nothing over it (${F('P20b')}). It fits the width held upright and the height turned (${F('P20f')}). Pinch and double-tap zoom into it; a page is never cropped to fill.`],
      ['A tap: the controls', `A tap shows the controls and a second hides them; a tap never turns the page (${F('P20c')}). At the top: ⌄, the book and its chapter, Chapters, and ⋯. At the foot: <code>3 of 24</code> and the book’s progress. They rest after <code>2.5 s</code>.`],
      ['Turning', `A swipe turns the page, the way the book reads. Left to right, the next page comes from the right; right to left, from the left, and the progress fills from the right (${F('P20d')}). The book’s direction is the author’s, set in the Studio; the reader does not change it.`],
      ['Scroll', `A webtoon reads as one column, full width, top to bottom, with no page turn (${F('P20e')}). Its controls are the same, with no page count; the progress is how far down.`],
      ['Chapters', `Chapters lists the book’s chapters with each one’s first page, its page range, and a tick on the one you are in (${F('P20g')}). Pressing one opens its first page.`],
      ['Where you are', `The device keeps the page you are on, per book. <code>Continue</code> opens it. A newer edition that no longer has that page opens the chapter it was in.`],
      ['An older Player', `A Player that cannot read the comic document shows the book with <code>Update app</code> and fetches nothing (${F('P20h')}; call 28).`],
      ['Words', `Labels only: Graphic novel, pages, Continue, Page, Chapters, Update app. Chapter titles and every word on a page are the author’s.`],
    ],
    next: `Try next: “two pages side by side on a Fold” · “a comic file added from the phone” · “the next chapter, released”`,
  },
];

// ---- assemble ---------------------------------------------------------------------------------
const turnOrder = [...TURNS].reverse(); // newest first, as in the Studio master
const all = TURNS.flatMap((t) => FRAMES[t.id]);
const radius = (f) => (f.w === 390 ? 'border-radius:40px' : f.w === 844 ? 'border-radius:28px' : 'border-radius:22px');
const card = (f) => `<div class="dv-opt" id="${f.id.toLowerCase()}"><div class="dv-olabel"><a class="dv-oid" href="#${f.id.toLowerCase()}">${f.id}</a>${esc(f.title)}</div><div class="dv-card" style="width:${f.w}px;max-width:none;${radius(f)}">${f.markup}</div></div>`;
const section = (t) => {
  const frames = FRAMES[t.id];
  return `<section class="dv-turn" id="${t.id}"><div class="dv-thd"><a class="dv-tid" href="#${t.id}">${t.id.toUpperCase()}</a><span class="dv-tname">${esc(t.name)}</span></div><p class="dv-next">${t.date ?? DATE} · ${t.status ?? 'Approved'} · ${frames.length} frames. ${t.lead}</p><div class="dv-opts" style="margin-top:22px">${frames.map(card).join('\n')}</div>${t.rules.map(([title, body], i) => `<p class="dv-rule"><b>${i + 1} · ${esc(title)}.</b> ${body}</p>`).join('\n')}<p class="dv-next">${t.next}</p></section>\n`;
};

const intro = `<section class="dv-turn" id="t0" style="padding:36px 44px 28px">
  <div style="max-width:760px;display:flex;flex-direction:column;gap:10px">
    <div style="font:650 20px/1.2 var(--font-sans);letter-spacing:-0.02em;color:var(--dv-ink)">Arke Player · design master</div>
    <div style="font:500 13px/1.5 var(--font-sans);color:var(--dv-ink)"><a href="#${TURNS.at(-1).id}">Latest: ${TURNS.at(-1).id.toUpperCase()} · ${esc(TURNS.at(-1).name.split(' — ')[0])}</a> · ${DATE}</div>
    <div style="font:400 13px/1.65 var(--font-sans);color:var(--dv-ink-body)">A phone app for what is made in Arke: worlds shared through an Arke account, and Arke packages and standard files — EPUB, PDF, audio, video — added from the phone, watched, heard, read and played. It hosts the Studio’s players — the interactive player (<a href="${STUDIO}#t156">Studio 156</a>), the visual novel (<a href="${STUDIO}#t174">174</a>), the audiobook (<a href="${STUDIO}#t186">186</a>, <a href="${STUDIO}#t211">211</a>, <a href="${STUDIO}#t212">212</a>) and the show page (<a href="${STUDIO}#t199">199</a>) — and adds the shelves, sharing, packages and downloads around them. Turns are numbered P1, P2… and frames P1a… so they never share a number with the <a href="${STUDIO}">Studio master</a>. Frames are 390 × 844 for a phone, 844 × 390 turned, 984 × 1092 for a Fold7 open. The sample is The Undersong, shared by Helen Marsh with Jonah Pike. <a href="review.html">Review page</a> · <a href="notes.md">Notes</a></div>
    <div style="font:400 13px/1.65 var(--font-sans);color:var(--dv-ink-body)"><b style="color:var(--dv-ink)">Turns.</b> ${TURNS.map((t) => `<a href="#${t.id}">${t.id.toUpperCase()} · ${esc(t.name.split(' — ')[0])}</a>`).join(' · ')}</div>
    <div style="font:400 13px/1.65 var(--font-sans);color:var(--dv-ink-body)"><b style="color:var(--dv-ink)">Calls for the owner.</b> 1 · When a share ends, its downloads go too (drawn so, <a href="#p2g">P2g</a>). 2 · The Player runs the Studio’s web player modules inside a native shell, rather than players written again (drawn so, <a href="#p3">P3</a>). 3 · A world package — a ZIP of a world’s name, logline, key art and its publications — is the file people add; its extension and schema go to SPEC-048 (<a href="#p2">P2</a>). 4 · The Studio’s Share sheet, who and which productions, is its own turn in the Studio master. 5 · The worlds to install are a list that ships with the app, each package pinned by its SHA-256 as the Studio pins its Sample world; a catalogue served by the Arke cloud can replace it (drawn so and approved, <a href="#p9">P9</a>). 6 · The Undersong is published as a world package (182 MB, ADR 0005) beside the Studio’s 1.6 GB editable world, which the Player never opens; the package format is owed to SPEC-048. 7 · World import was left out of the MVP; P9 needs no account, and whether it joins the MVP is open. 8 · Arke’s list of worlds is also fetched from one Arke address, at most once a day, the list in the app as the floor, so a newer edition shows without an app update (drawn so and approved, <a href="#p12">P12</a>). 9 · A world’s update downloads only when Update is pressed, never on its own (drawn so and approved, <a href="#p12">P12</a>). 10 · A moment’s picture comes Wide and Tall, the Tall made in the Studio from the Wide; a phone in portrait shows the Tall one over the whole screen, everything else the Wide (drawn so and approved, <a href="#p14">P14</a>). 11 · Worlds becomes Discover, what you can get, beside Library, what you have; Discover leads with productions and new chapters, and its teasers are the author’s choice (asked 24 October 2026, drawn so and approved, <a href="#p15">P15</a>). 12 · A world comes as a base and a part per release, and a new part comes on its own over Wi-Fi; a new edition still waits for Update (drawn so and approved, <a href="#p15">P15</a>). 13 · A new chapter is notified by the phone itself, per world, off until turned on (drawn so and approved, <a href="#p15">P15</a>). 14 · A production’s cover comes Wide and Tall, the Tall made in the Studio from the Wide as a moment’s is (Studio <a href="${STUDIO}#t235">235</a>); a poster and a phone’s feature show the Tall, and one without shows the Wide whole over its blur. The Studio half is its own turn (drawn so and approved, <a href="#p16">P16</a>). 15 · Discover’s feature and band are named in Arke’s list; with neither named, the newest release and the newest world (drawn so and approved, <a href="#p16">P16</a>). 16 · The tabs as a pill floating over the page, as Netflix’s are, in place of the bar and the Fold’s rail (drawn so and chosen by the owner, <a href="#p16h">P16h</a> – <a href="#p16j">P16j</a>). 17 · Music is a production — Album, Single or Soundtrack — with its own group in a world, never a loose take (asked and approved 24 October 2026, drawn so, <a href="#p17">P17</a>). 18 · A music cover is square, 1:1 at 1024 × 1024, the fourth picture shape (drawn so and approved, <a href="#p17">P17</a>). 19 · Lyrics are shown as written, not timed to the song, until the Studio’s sections time them (drawn so and approved, <a href="#p17e">P17e</a>; Studio 238 call 8). 20 · A song keeps no place and never joins Continue (drawn so and approved, <a href="#p17">P17</a>). 21 · An interactive movie or visual novel reaches the Player as a production package of its own, holding one story document compiled from the Studio’s routing (the rules its web export plays) with its clips or pictures. The Player says which versions of that document it reads, and Arke’s list offers a story only to a Player that can read it (approved 28 October 2026, <a href="#p18">P18</a>). 22 · The Player plays a story natively, its rules written again in Dart and held to the Studio’s by shared fixtures: every route of First Contact replays through both and must reach the same scenes and facts. This revises call 2 for stories. Hosting the Studio’s web player is the alternative: one engine, but P3’s controls, offline files and the lock screen would be a web page’s (approved). 23 · A choice the story has closed shows only when the author wrote a reason for it, and a listener is never shown the facts (drawn so and approved, <a href="#p18d">P18d</a>). 24 · The author’s half, Export → Arke Player for an interactive movie or a visual novel, is a Studio turn of its own, drawn next (approved). 25 · A story plays itself and stops only for a choice of two or more, a closed choice shown with its reason counting as one. A tap shows its controls and never moves on, and a lone way on plays straight through, with no pause, no label and no row in the route. This withdraws P4d’s tap and P18’s <code>Auto</code> (the owner’s direction, 28 October 2026; approved, <a href="#p19">P19</a>). 26 · Narration is on wherever a story has voices; turned off, it stays off for that story on this device, kept with where you are. One setting for every story, in You, is the alternative (approved, <a href="#p19b">P19b</a>). 27 · An interactive movie’s controls are a film’s, P3a’s back 10 and forward 10 included; it has no beats, Log or Narration (approved, <a href="#p19f">P19f</a>). 28 · A graphic novel reaches the Player as a production package of its own, world package schema 7, its pages listed in reading order in one comic document and pinned under the production’s <code>comic</code>; a Player that cannot read it shows <code>Update app</code> (approved, <a href="#p20">P20</a>). 29 · Pages are read natively, a whole page at a time and never cropped; panel-by-panel guided view is not in this version (approved, <a href="#p20b">P20b</a>). 30 · The book’s direction is the author’s; the reader turns it that way and does not offer to change it (approved, <a href="#p20d">P20d</a>). 31 · A comic file added from the phone (CBZ, <a href="#p7">P7</a>) stays refused for now; it can open in this reader later (approved).</div>
  </div>
</section>
`;

// The document chrome (dv-* styles) is the Studio master's, frozen in dv-chrome.css.
const chrome = read('dv-chrome.css');

const master = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Arke Player · design master</title>
<script src="./runtime/support.js"></script>
</head>
<body>
<x-dc>
<helmet>
<meta name="design_doc_mode" content="canvas">
${['fonts', 'colors', 'typography', 'spacing', 'effects'].map((n) => `<link rel="stylesheet" href="${TOKENS}/${n}.css">`).join('\n')}
<link rel="stylesheet" href="frames.css">
<script src="runtime/theme-switch.js"></script>
<style>
${chrome}
/* The Player's frames are phones: the cards round like one. */
.dv-opts{gap:40px 36px}
</style>
</helmet>
${intro}${turnOrder.map(section).join('')}</x-dc>
</body>
</html>
`;

const review = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Arke Player · review</title>${['fonts', 'colors', 'typography', 'spacing', 'effects'].map((n) => `<link rel="stylesheet" href="${TOKENS}/${n}.css">`).join('')}<link rel="stylesheet" href="frames.css">
<style>body{margin:0;background:#EFEEEB;color:#1a1a1a;font-family:var(--font-sans)}html.dark body{background:#131313;color:#ededed}.rv{padding:32px;display:flex;flex-direction:column;gap:44px}.rv>header{display:flex;gap:12px;align-items:center;font:var(--type-ui)}.rv>header button{font:var(--type-ui);padding:6px 12px;border-radius:8px;border:1px solid #888;background:none;color:inherit;cursor:pointer}.rv a{color:inherit}.rv h2{font:var(--type-h3);margin:0 0 6px}.rv .lead{font:var(--type-body);max-width:1100px;opacity:.75;margin:0 0 18px}.rv .row{display:flex;flex-wrap:wrap;gap:36px}.rv figure{margin:0;display:flex;flex-direction:column;gap:8px}.rv figcaption{font:var(--type-ui)}.rv .fr{overflow:hidden;box-shadow:0 0 0 1px rgba(0,0,0,.12),0 4px 18px rgba(0,0,0,.08);width:max-content}.rv .rules{max-width:1100px;margin-top:20px;display:flex;flex-direction:column;gap:8px}.rv .dv-rule{margin:0;padding:10px 14px;border-left:2px solid #2a78d6;background:rgba(42,120,214,.05);font:var(--type-ui);font-weight:400;line-height:1.6}.rv .dv-rule code{font:inherit;background:rgba(0,0,0,.06);padding:0 4px;border-radius:3px}.rv .dv-oid{font-weight:600}</style></head>
<body><div class="rv"><header><b>Arke Player · design master</b><button type="button" onclick="document.documentElement.classList.toggle('dark')">Light / dark</button><a href="Arke%20Player.dc.html">Design master</a><a href="notes.md">Notes</a></header>
${TURNS.map((t) => `<section id="${t.id}"><h2><a href="#${t.id}">${t.id.toUpperCase()}</a> · ${esc(t.name)}</h2><p class="lead">${t.lead}</p><div class="row">${FRAMES[t.id].map((f) => `<figure id="${f.id.toLowerCase()}"><figcaption><a href="#${f.id.toLowerCase()}">${f.id}</a> ${esc(f.title)}</figcaption><div class="fr" style="${radius(f)}">${f.markup}</div></figure>`).join('')}</div><div class="rules">${t.rules.map(([title, body], i) => `<p class="dv-rule"><b>${i + 1} · ${esc(title)}.</b> ${body.replaceAll('href="#', 'href="#')}</p>`).join('')}</div></section>`).join('\n')}
</div></body></html>
`;

// ---- checks: what design/check.mjs asks of the master, and that every frame closes -----------
const problems = [];
for (const f of all) {
  for (const tag of ['div', 'span']) {
    const open = (f.markup.match(new RegExp(`<${tag}\\b`, 'g')) ?? []).length;
    const shut = (f.markup.match(new RegExp(`</${tag}>`, 'g')) ?? []).length;
    if (open !== shut) problems.push(`${f.id}: ${open} <${tag}> against ${shut} </${tag}>`);
  }
  const raw = f.markup.match(/\bfont(?:-size)?\s*:\s*(?:[0-9]{3}\s+)?[0-9]+(?:\.[0-9]+)?px/g);
  if (raw) problems.push(`${f.id}: raw font sizes ${raw.join(', ')}`);
  for (const m of f.markup.matchAll(/src="assets\/([^"]+)"/g)) if (!fs.existsSync(path.join(here, 'assets', m[1]))) problems.push(`${f.id}: missing asset ${m[1]}`);
}
const ids = [...master.matchAll(/\bid="([^"]+)"/g)].map((m) => m[1]);
const dupes = ids.filter((id, i) => ids.indexOf(id) !== i);
if (dupes.length) problems.push(`duplicate ids: ${[...new Set(dupes)].join(', ')}`);
for (const m of master.matchAll(/href="#([^"]+)"/g)) if (!ids.includes(m[1])) problems.push(`anchor with no target: #${m[1]}`);
if (problems.length) {
  console.error(`arke-player: ${problems.length} problem(s)`);
  for (const p of problems) console.error(' - ' + p);
  process.exit(1);
}

write('Arke Player.dc.html', master);
write('review.html', review);
console.log(`Wrote Arke Player.dc.html and review.html: ${TURNS.length} turns, ${all.length} frames, ${TURNS.reduce((n, t) => n + t.rules.length, 0)} rules.`);
